#include<bits/stdc++.h>
using namespace std;
#define all(v)      v.begin(),v.end()
#define pb          push_back
#define REP(i,b,e)  for(int i=(b);i<(int)(e);++i)
#define over(x)     {cout<<(x)<<endl;return;}
int n,q,r;
int a[300005];
int sum[300005];
int ql[300005],qr[300005];
int ans[300005];
int cnt[300005],cnt2[300005];
void Main() {
	cin>>n>>q>>r;
	REP(i,0,n)cin>>a[i];
	sum[0]=0;
	int B=sqrt(r);
	REP(i,0,n)sum[i+1]=sum[i]+(a[i]<=B);
	REP(i,0,q){
		int x,y;
		cin>>x>>y;
		--x,--y;
		ql[i]=x;qr[i]=y;
		ans[i]=0;
		if(sum[y+1]-sum[x]<(y-x+1)/2)ans[i]=(y-x+1)/2-sum[y+1]+sum[x];
	}
	REP(i,0,B){
		REP(j,0,n+1)cnt[j]=cnt2[j]=0;
		REP(j,0,n){
			cnt[j+1]=cnt[j]+(a[j]<=i);
			cnt2[j+1]=cnt2[j]+(a[j]<=r/(i+1));
		}
		REP(j,0,q){
			int x=ql[j],y=qr[j],l=y-x+1;
			int c1=cnt2[y+1]-cnt2[x],c2=cnt[y+1]-cnt[x];
			ans[j]=max(ans[j],min((l-c1-c2+1)/2,l/2-c2));
		}
	}
	REP(i,0,q)cout<<ans[i]<<' ';
	cout<<endl;
}
void TC() {
    int tc=1;
    cin>>tc;
	while(tc--){
		Main();
		cout.flush();
	}
}
signed main() {
	return cin.tie(0),cout.tie(0),ios::sync_with_stdio(0),TC(),0;
}
